import re
from pathlib import Path

ВХІД = Path("дані") / "журнал.txt"
ЧАС_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})")
ТИП_RE = re.compile(r"^  (\S[^:]*):(?: |$)")
АБЕТКА = "абвгґдеєжзиіїйклмнопрстуфхцчшщьюя"


def ключ_абетки(текст):
    return tuple(
        АБЕТКА.find(c) if c in АБЕТКА else len(АБЕТКА) + ord(c)
        for c in текст.casefold()
    )


def читати_записи(шлях):
    записи = []
    for рядок in шлях.read_text(encoding="utf-8-sig").splitlines():
        if ЧАС_RE.match(рядок):
            записи.append([рядок])
        elif записи:
            записи[-1].append(рядок)
    return записи


def тип_винятку(запис):
    тип = None
    for рядок in запис[1:]:
        м = ТИП_RE.match(рядок)
        if м:
            тип = м.group(1).rstrip()
    return тип


def main():
    статистика = {}
    for запис in читати_записи(ВХІД):
        тип = тип_винятку(запис)
        if тип is None:
            continue
        час = ЧАС_RE.match(запис[0]).group(1)
        if тип in статистика:
            n, перший, останній = статистика[тип]
            статистика[тип] = [n + 1, min(перший, час), max(останній, час)]
        else:
            статистика[тип] = [1, час, час]

    for тип, (n, перший, останній) in sorted(
        статистика.items(),
        key=lambda kv: (-kv[1][0], ключ_абетки(kv[0])),
    ):
        print(f"{тип}: {n} ({перший}, {останній})")


if __name__ == "__main__":
    main()

